workflow_template.source:
schema: t3.workflow/v1
id: nightly-check
title: Nightly check
home: { project: app }
triggers:
  nightly: { kind: cron, expr: "0 3 * * *", tz: America/Sao_Paulo }
budget: { steps: 10, wall: 1h, tokens: 200000 }
fatigue: { consecutiveFailures: 3 }
models:
  lead: { provider: claude, model: claude-haiku-5-5 }
nodes:
  look:
    kind: agent
    model: $lead
    prompt: Check the project and answer in JSON.
    workspace: { project: app, readOnly: true }
    output: { news: { type: string } }
  done:
    kind: output
    status: no_change
    value: {}
    report: "{{ nodes.look.output.news }}"
edges: [look -> done]
